import { useMemo, useState } from 'react';

export type UserStatus = 'active' | 'disabled';

export interface JinxUser {
  id: string;
  name: string;
  role: string;
  status: UserStatus;
}

interface UsersTableProps {
  users: JinxUser[];
}

const PAGE_SIZE = 10;

function StatusBadge({ status }: { status: UserStatus }) {
  const isActive = status === 'active';
  return (
    <span
      className={`jx-badge ${isActive ? 'jx-badge--success' : 'jx-badge--danger'}`}
    >
      {isActive ? 'Активен' : 'Отключён'}
    </span>
  );
}

export default function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount);

  const pageUsers = useMemo(() => {
    const start = (safePage - 1) * PAGE_SIZE;
    return users.slice(start, start + PAGE_SIZE);
  }, [users, safePage]);

  const goTo = (target: number) => {
    setPage(Math.min(Math.max(target, 1), pageCount));
  };

  return (
    <div className="jx-panel jx-stack">
      <table className="jx-table">
        <thead>
          <tr>
            <th scope="col">Имя</th>
            <th scope="col">Роль</th>
            <th scope="col">Статус</th>
          </tr>
        </thead>
        <tbody>
          {pageUsers.map((user) => (
            <tr key={user.id}>
              <td>{user.name}</td>
              <td>{user.role}</td>
              <td>
                <StatusBadge status={user.status} />
              </td>
            </tr>
          ))}
          {pageUsers.length === 0 && (
            <tr>
              <td colSpan={3} className="jx-text-muted">
                Нет пользователей
              </td>
            </tr>
          )}
        </tbody>
      </table>

      <nav className="jx-pagination" aria-label="Постраничная навигация">
        <button
          type="button"
          className="jx-button jx-button--ghost"
          onClick={() => goTo(safePage - 1)}
          disabled={safePage === 1}
        >
          Назад
        </button>

        <span className="jx-pagination__status">
          Страница {safePage} из {pageCount}
        </span>

        <button
          type="button"
          className="jx-button jx-button--ghost"
          onClick={() => goTo(safePage + 1)}
          disabled={safePage === pageCount}
        >
          Вперёд
        </button>
      </nav>
    </div>
  );
}

